const body = $input.first().json.body || {};
const action = String(body.action || '').trim().toUpperCase();
const supported = new Set([
  'GET_PARENT_CATEGORIES', 'SEARCH_SUBJECTS', 'GET_SCHEMA', 'GET_DIRECTORY',
  'CHECK_VENDOR_CODES',
  'UPSERT_CATEGORY_PROJECTION', 'GET_CATEGORY_PROJECTION', 'DELETE_CATEGORY_PROJECTION',
  'UPSERT_RUNTIME_CONFIG', 'GET_RUNTIME_CONFIG',
]);
if (!supported.has(action)) {
  return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'unsupported_action', message: '不支持的管理动作' } }];
}
if (['UPSERT_CATEGORY_PROJECTION', 'DELETE_CATEGORY_PROJECTION', 'UPSERT_RUNTIME_CONFIG'].includes(action)) {
  return [{ json: {
    action: 'INVALID', httpStatus: 410, ok: false,
    error: 'MIGRATED_TO_POSTGRESQL', code: 'MIGRATED_TO_POSTGRESQL',
    message: 'WB 运行配置和类目投影已迁移到 MerchRoute PostgreSQL，请调用 /api/v1/wb/runtime/* 或 MerchRoute 服务端接口'
  } }];
}
const payload = body.payload && typeof body.payload === 'object' && !Array.isArray(body.payload) ? body.payload : {};
const storeId = String(body.storeId || payload.storeId || '').trim();
const storeAlias = String(body.storeAlias || payload.storeAlias || '').trim().toLowerCase();
if (storeId && !/^[a-f0-9-]{36}$/i.test(storeId)) {
  return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'invalid_store_id', message: 'storeId 必须是 UUID' } }];
}
if (storeAlias && !/^[a-z0-9][a-z0-9-]{1,31}$/.test(storeAlias)) {
  return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'invalid_store_alias', message: 'storeAlias 格式无效' } }];
}
if (Boolean(storeId) !== Boolean(storeAlias)) {
  return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'incomplete_store_context', message: 'storeId/storeAlias 必须同时提供' } }];
}
const suppliedRequestRef = String(body.requestRef || '').trim();
if (suppliedRequestRef && (suppliedRequestRef.length > 240 || !/^[A-Za-z0-9._:|-]+$/.test(suppliedRequestRef))) {
  return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'invalid_request_ref', message: 'requestRef 格式无效' } }];
}
if (storeId && !suppliedRequestRef) {
  return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'request_ref_required', message: '多店铺读取必须提供稳定 requestRef' } }];
}
const requestRef = suppliedRequestRef || ('p003:' + action + ':' + Date.now());
const out = { action, payload, storeId, storeAlias, requestRef, gatewayMode: storeId ? 'MERCHROUTE_VAULT' : 'LEGACY_CREDENTIAL' };
if (['GET_PARENT_CATEGORIES', 'SEARCH_SUBJECTS', 'GET_SCHEMA', 'GET_DIRECTORY'].includes(action)) {
  const locale = String(payload.locale || 'ru').trim().toLowerCase();
  if (!['ru', 'zh'].includes(locale)) {
    return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'invalid_locale', message: 'locale 仅允许 ru/zh' } }];
  }
  out.locale = locale;
}
if (action === 'SEARCH_SUBJECTS') {
  out.name = String(payload.name || payload.query || '').trim();
  out.parentID = payload.parentID == null || payload.parentID === '' ? '' : String(payload.parentID);
  out.limit = Math.max(1, Math.min(1000, Math.trunc(Number(payload.limit || 100))));
  out.offset = Math.max(0, Math.trunc(Number(payload.offset || 0)));
}
if (action === 'GET_SCHEMA') {
  out.subjectId = Math.trunc(Number(payload.subjectId));
  if (!Number.isInteger(out.subjectId) || out.subjectId <= 0) {
    return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'invalid_subject_id', message: 'subjectId 必须是正整数' } }];
  }
}
if (action === 'GET_DIRECTORY') {
  const directory = String(payload.directory || '').trim().toLowerCase();
  const allowed = new Set(['colors', 'kinds', 'countries', 'seasons', 'vat', 'tnved']);
  if (!allowed.has(directory)) {
    return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'invalid_directory', message: 'directory 仅允许 colors/kinds/countries/seasons/vat/tnved' } }];
  }
  out.directory = directory;
  if (directory === 'tnved') {
    out.subjectId = Math.trunc(Number(payload.subjectId));
    if (!Number.isInteger(out.subjectId) || out.subjectId <= 0) {
      return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'invalid_subject_id', message: '查询 tnved 时 subjectId 必填' } }];
