  if (!vendorCodes.length || vendorCodes.length > 30 || vendorCodes.some((value) => value.length > 100 || !/^[A-Za-z0-9._-]+$/.test(value))) {
    return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'invalid_vendor_codes', message: 'vendorCodes 必须包含 1 到 30 个合法且唯一的卖家商品编码' } }];
  }
  out.vendorCodes = vendorCodes;
}
if (['GET_CATEGORY_PROJECTION', 'UPSERT_CATEGORY_PROJECTION', 'DELETE_CATEGORY_PROJECTION'].includes(action)) {
  out.categoryKey = String(payload.categoryKey || '').trim();
  if (!/^[a-z0-9][a-z0-9_-]{1,79}$/.test(out.categoryKey)) {
    return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'invalid_category_key', message: 'categoryKey 格式无效' } }];
  }
}
