  out.importRoot = String(payload.importRoot || '').trim();
  if (!out.importRoot || out.importRoot.includes('\0')) {
    return [{ json: { action: 'INVALID', httpStatus: 400, ok: false, error: 'invalid_import_root', message: 'importRoot 必须是绝对目录且不能包含 NUL 字符' } }];
