    const retryAfterMs = retryAfterMilliseconds(raw, body);
    return [{ json: {
      httpStatus: safeStatus, ok: false, action: request.action,
      error: status === 401 || status === 403 ? 'wb_auth_error' : (status === 429 ? 'wb_rate_limited' : 'wb_api_error'),
