return (async () => {
  const values = {};
  values["category_key"] = (() => { const $json = ($input.first()?.json || {}); return ($('Normalize Admin Request').first().json.categoryKey); })();
  if ("wb_category_templates" === 'wb_runtime_config') {
    if ("Load Existing Category Projection" === 'Load Dispatch Config') {
      const gate = $getWorkflowStaticData('global');
      gate.runtimeNetworkRecovery = gate.runtimeNetworkRecovery && typeof gate.runtimeNetworkRecovery === 'object'
        ? gate.runtimeNetworkRecovery : {};
      const recovery = gate.runtimeNetworkRecovery;
      if (recovery.active === true && Number.isFinite(Date.parse(String(recovery.nextAttemptAt || '')))
          && Date.parse(String(recovery.nextAttemptAt)) > Date.now()) {
