const crypto = require('crypto');
const path = require('path');
const request = $('Normalize Admin Request').first().json || {};
const raw = String(request.importRoot || '').trim();
const isWindows = /^[A-Za-z]:[\\/]/.test(raw) || /^\\\\/.test(raw);
