if (!(isWindows || raw.startsWith('/'))) throw new Error('INVALID_IMPORT_ROOT: importRoot 必须是绝对路径');
const normalized = api.normalize(raw);
const parsed = api.parse(normalized);
const withoutTrailing = normalized.replace(/[\\/]+$/, '') || parsed.root;
const rootWithoutTrailing = parsed.root.replace(/[\\/]+$/, '');
if (!withoutTrailing || normalized === parsed.root || withoutTrailing.toLowerCase() === rootWithoutTrailing.toLowerCase()) throw new Error('INVALID_IMPORT_ROOT: 禁止使用磁盘或文件系统根目录');
const current = $input.all().map((item) => item.json).find((row) => row && row.config_id) || {};
const canonical = isWindows ? withoutTrailing.replace(/\\/g, '/').toLowerCase() : withoutTrailing;
